CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT NOT NULL DEFAULT '', birthday TEXT NOT NULL DEFAULT '', "passwordHash" TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')));
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS courses (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, level TEXT NOT NULL, duration INTEGER NOT NULL, tuition INTEGER NOT NULL, lessons INTEGER NOT NULL, audience TEXT NOT NULL, image TEXT NOT NULL, description TEXT NOT NULL, material TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS teachers (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, degree TEXT NOT NULL, experience INTEGER NOT NULL, specialty TEXT NOT NULL, image TEXT NOT NULL, description TEXT NOT NULL, achievements TEXT NOT NULL DEFAULT '', nationality TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS classes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "courseId" INTEGER NOT NULL REFERENCES courses(id), "teacherId" INTEGER NOT NULL REFERENCES teachers(id), name TEXT UNIQUE NOT NULL, "startDate" TEXT NOT NULL, "endDate" TEXT NOT NULL, schedule TEXT NOT NULL, campus TEXT NOT NULL, capacity INTEGER NOT NULL, weekdays TEXT NOT NULL DEFAULT '[]', "startTime" TEXT NOT NULL DEFAULT '', "endTime" TEXT NOT NULL DEFAULT '', room TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'enrolling');
CREATE TABLE IF NOT EXISTS enrollments (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "userId" INTEGER REFERENCES users(id), "classId" INTEGER NOT NULL REFERENCES classes(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, birthday TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled')), grades TEXT NOT NULL DEFAULT '{}', "createdAt" TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), "verifiedAt" TEXT, "verifiedBy" INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS questions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, prompt TEXT NOT NULL, options TEXT NOT NULL, answer INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS placement_results (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "userId" INTEGER REFERENCES users(id) ON DELETE SET NULL, score INTEGER NOT NULL, total INTEGER NOT NULL, level TEXT NOT NULL, "createdAt" TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), review TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS news (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, date TEXT NOT NULL, image TEXT NOT NULL, excerpt TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contacts (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, message TEXT NOT NULL, "createdAt" TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), status TEXT NOT NULL DEFAULT 'new', note TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'consultation', age INTEGER, "courseId" INTEGER REFERENCES courses(id) ON DELETE SET NULL, campus TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS placement_attempts (token TEXT PRIMARY KEY, "userId" INTEGER REFERENCES users(id), questions TEXT NOT NULL, expires BIGINT NOT NULL, result TEXT);
CREATE TABLE IF NOT EXISTS materials (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "classId" INTEGER NOT NULL REFERENCES classes(id), title TEXT NOT NULL, lesson TEXT NOT NULL DEFAULT '', filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, content BYTEA NOT NULL, "createdAt" TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "actorId" INTEGER REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, resource TEXT NOT NULL, "recordId" INTEGER, "createdAt" TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')));
CREATE UNIQUE INDEX IF NOT EXISTS active_enrollment ON enrollments(email, "classId") WHERE status != 'cancelled';
CREATE UNIQUE INDEX IF NOT EXISTS active_student_enrollment ON enrollments("userId","classId") WHERE status != 'cancelled' AND "userId" IS NOT NULL;
CREATE INDEX IF NOT EXISTS enrollments_user_class ON enrollments("userId","classId");
